// Prepare a LARGE batch of items to grade. In production, replace this with a read of the job's
// invocation set (or a Split In Batches over thousands of items). Each item becomes one REF
// verdict question against the closed choice vocabulary. The listing's batch_threshold and the
// REF pins travel with the batch so the coordination layer can decide + record deterministically.
const jobId = $json.jobId || 'batch-demo';
const threshold = $json.threshold ?? 0.01;      // pass rate the listing declared
const minConfidence = $json.minConfidence ?? 0.6;
// demo items; swap for the real invocation set
const items = ($json.items && Array.isArray($json.items) && $json.items.length)
  ? $json.items
  : Array.from({length: 50}, (_,i) => ({ item_id: 'item-'+i, output: 'delivered work sample '+i }));
// one n8n item per batch item, each carrying the state to judge + the single verdict question
return items.map((it) => ({ json: {
  jobId, threshold, minConfidence,
  item_id: it.item_id,
  state: typeof it.output === 'string' ? it.output : JSON.stringify(it.output),
  questions: [{ id: 'verdict', kind: 'choice', text: 'Was the work delivered as specified?',
    options: 'delivered_as_specified, delivered_with_defects, not_delivered, cannot_determine' }]
}}));

// Grade + aggregate: keep each item's FULL distribution (the recovered Jev power), decide the
// batch against the threshold, and shape the outcome for the coordination layer to record. This
// mirrors the verdict crate's batch::grade_item + aggregate — do the same offline-recomputable math.
const rows = $input.all().map(i => i.json);
const threshold = rows[0]?.threshold ?? 0.01;
const jobId = rows[0]?.jobId ?? 'batch';
const minConf = rows[0]?.minConfidence ?? 0.6;
let conformant=0, nonconformant=0, nograde=0; const items=[];
for (const r of rows) {
  // the typesafe node returns answers on the item; find the verdict answer + its distribution
  const a = (r.answers || []).find(x => x.id === 'verdict') || r;
  const dist = a.probabilities || {};
  const conf = a.confidence ?? 0;
  let choice = (a.value || 'cannot_determine');
  if (conf < minConf) choice = 'cannot_determine';
  let verdict;
  if (choice === 'delivered_as_specified') { verdict='Conformant'; conformant++; }
  else if (choice === 'delivered_with_defects' || choice === 'not_delivered') { verdict='NonConformant'; nonconformant++; }
  else { verdict='NoGrade'; nograde++; }
  items.push({ item_id: r.item_id, choice, verdict, confidence: conf, distribution: dist });
}
const graded = conformant + nonconformant;
const failFraction = graded === 0 ? 1 : nonconformant/graded;
const batchVerdict = graded === 0 ? 'NoGrade' : (failFraction <= threshold ? 'Conformant' : 'NonConformant');
return [{ json: { jobId, mode: 'Calibrated', total: items.length, conformant, nonconformant, nograde,
  failFraction, threshold, verdict: batchVerdict, items } }];
